import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
// Register-blocked tiled direct 2D convolution (NCHW, contiguous, float32).
// Each CTA computes a 16x64 output tile; each of 256 threads computes 4 adjacent outputs.
// Input tiles (halo included) are staged cooperatively in shared memory per input channel.
.extern .shared .align 4 .b8 smem[];
.visible .entry conv2d_kernel(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 has_bias,
    .param .u32 OC,
    .param .u32 OH,
    .param .u32 OW,
    .param .u32 IC,
    .param .u32 H,
    .param .u32 W,
    .param .u32 KH,
    .param .u32 KW,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 dil_h,
    .param .u32 dil_w,
    .param .u32 in_tile_h,
    .param .u32 in_tile_w
)
{
    .reg .pred %p<20>;
    .reg .b32  %r<64>;
    .reg .b64  %rd<24>;
    .reg .f32  %f<12>;
    mov.u32 %r40, 16;                      // TILE_H
    mov.u32 %r46, 64;                      // TILE_W
    mov.u32 %r41, 256;                     // blockDim.x
    mov.u32 %r0, %tid.x;                   // tid
    div.u32 %r1, %r0, %r40;                // th = tid / 16
    rem.u32 %r2, %r0, %r40;                // tw = tid % 16 (column group)
    mov.u32 %r3, %ctaid.x;                 // 64-wide tile column
    mov.u32 %r4, %ctaid.y;                 // 16-high tile row
    mov.u32 %r5, %ctaid.z;                 // b*OC + oc
    ld.param.u32 %r6, [OC];
    rem.u32 %r7, %r5, %r6;                 // oc
    div.u32 %r8, %r5, %r6;                 // b
    ld.param.u32 %r9, [OH];
    ld.param.u32 %r10, [OW];
    mad.lo.u32 %r11, %r4, %r40, %r1;       // oh
    mul.lo.u32 %r51, %r2, 4;               // column-group base inside tile
    mad.lo.u32 %r12, %r3, %r46, %r51;      // ow base for 4 outputs
    setp.lt.u32 %p0, %r11, %r9;            // row valid
    add.u32 %r47, %r12, 0;
    add.u32 %r48, %r12, 1;
    add.u32 %r49, %r12, 2;
    add.u32 %r50, %r12, 3;
    setp.lt.u32 %p1, %r47, %r10;
    and.pred  %p13, %p0, %p1;
    setp.lt.u32 %p1, %r48, %r10;
    and.pred  %p14, %p0, %p1;
    setp.lt.u32 %p1, %r49, %r10;
    and.pred  %p15, %p0, %p1;
    setp.lt.u32 %p1, %r50, %r10;
    and.pred  %p16, %p0, %p1;
    ld.param.u32 %r13, [stride_h];
    ld.param.u32 %r14, [stride_w];
    ld.param.u32 %r15, [pad_h];
    ld.param.u32 %r16, [pad_w];
    mul.lo.u32 %r17, %r4, %r40;
    mul.lo.u32 %r17, %r17, %r13;
    sub.s32    %r17, %r17, %r15;           // ih0 signed
    mul.lo.u32 %r18, %r3, %r46;
    mul.lo.u32 %r18, %r18, %r14;
    sub.s32    %r18, %r18, %r16;           // iw0 signed
    ld.param.u32 %r19, [IC];
    ld.param.u32 %r20, [H];
    ld.param.u32 %r21, [W];
    ld.param.u32 %r22, [KH];
    ld.param.u32 %r23, [KW];
    ld.param.u32 %r24, [dil_h];
    ld.param.u32 %r25, [dil_w];
    ld.param.u32 %r26, [in_tile_h];
    ld.param.u32 %r27, [in_tile_w];
    mul.lo.u32 %r28, %r26, %r27;           // tile_size
    mov.u64 %rd0, smem;
    mov.f32 %f0, 0f00000000;               // acc0
    mov.f32 %f1, 0f00000000;               // acc1
    mov.f32 %f2, 0f00000000;               // acc2
    mov.f32 %f3, 0f00000000;               // acc3
    mov.u32 %r29, 0;                       // ic
LOOP_IC:
    setp.ge.u32 %p3, %r29, %r19;
    @%p3 bra STORE;
    mov.u32 %r30, %r0;                     // cooperative idx
LOAD_LOOP:
    setp.ge.u32 %p4, %r30, %r28;
    @%p4 bra LOAD_DONE;
    div.u32 %r31, %r30, %r27;              // ith
    rem.u32 %r32, %r30, %r27;              // itw
    add.s32 %r33, %r17, %r31;              // ih
    add.s32 %r34, %r18, %r32;              // iw
    mov.f32 %f4, 0f00000000;
    setp.lt.s32 %p5, %r33, 0;
    setp.ge.s32 %p6, %r33, %r20;
    or.pred  %p7, %p5, %p6;
    setp.lt.s32 %p8, %r34, 0;
    or.pred  %p7, %p7, %p8;
    setp.ge.s32 %p9, %r34, %r21;
    or.pred  %p7, %p7, %p9;
    @%p7 bra WRITE_SMEM;
    mad.lo.u32 %r35, %r8, %r19, %r29;
    mad.lo.u32 %r35, %r35, %r20, %r33;
    mad.lo.u32 %r35, %r35, %r21, %r34;
    cvt.u64.u32 %rd1, %r35;
    shl.b64     %rd1, %rd1, 2;
    ld.param.u64 %rd2, [in_ptr];
    add.u64     %rd2, %rd2, %rd1;
    ld.global.f32 %f4, [%rd2];
WRITE_SMEM:
    cvt.u64.u32 %rd3, %r30;
    shl.b64     %rd3, %rd3, 2;
    add.u64     %rd4, %rd0, %rd3;
    st.shared.f32 [%rd4], %f4;
    add.u32 %r30, %r30, %r41;
    bra LOAD_LOOP;
LOAD_DONE:
    bar.sync 0;
    mov.u32 %r36, 0;                       // kh
LOOP_KH:
    setp.ge.u32 %p10, %r36, %r22;
    @%p10 bra COMPUTE_DONE;
    mul.lo.u32 %r37, %r1, %r13;            // th*stride_h
    mad.lo.u32 %r37, %r36, %r24, %r37;     // ih_l
    mov.u32 %r38, 0;                       // kw
LOOP_KW:
    setp.ge.u32 %p11, %r38, %r23;
    @%p11 bra NEXT_KH;
    mul.lo.u32 %r39, %r51, %r14;           // (tw*4)*stride_w
    mad.lo.u32 %r39, %r38, %r25, %r39;     // iw_l0
    mad.lo.u32 %r52, %r37, %r27, %r39;     // smem idx0
    add.u32 %r53, %r52, %r14;              // + stride_w
    add.u32 %r54, %r53, %r14;
    add.u32 %r55, %r54, %r14;
    cvt.u64.u32 %rd5, %r52;
    shl.b64     %rd5, %rd5, 2;
    add.u64     %rd5, %rd0, %rd5;
    ld.shared.f32 %f4, [%rd5];
    cvt.u64.u32 %rd6, %r53;
    shl.b64     %rd6, %rd6, 2;
    add.u64     %rd6, %rd0, %rd6;
    ld.shared.f32 %f5, [%rd6];
    cvt.u64.u32 %rd7, %r54;
    shl.b64     %rd7, %rd7, 2;
    add.u64     %rd7, %rd0, %rd7;
    ld.shared.f32 %f6, [%rd7];
    cvt.u64.u32 %rd8, %r55;
    shl.b64     %rd8, %rd8, 2;
    add.u64     %rd8, %rd0, %rd8;
    ld.shared.f32 %f7, [%rd8];
    mad.lo.u32 %r43, %r7, %r19, %r29;
    mad.lo.u32 %r43, %r43, %r22, %r36;
    mad.lo.u32 %r43, %r43, %r23, %r38;
    cvt.u64.u32 %rd9, %r43;
    shl.b64     %rd9, %rd9, 2;
    ld.param.u64 %rd10, [wt_ptr];
    add.u64     %rd10, %rd10, %rd9;
    ld.global.f32 %f8, [%rd10];            // weight w[oc,ic,kh,kw]
    fma.rn.f32 %f0, %f4, %f8, %f0;         // acc0 += in0 * w
    fma.rn.f32 %f1, %f5, %f8, %f1;         // acc1 += in1 * w
    fma.rn.f32 %f2, %f6, %f8, %f2;         // acc2 += in2 * w
    fma.rn.f32 %f3, %f7, %f8, %f3;         // acc3 += in3 * w
    add.u32 %r38, %r38, 1;
    bra LOOP_KW;
NEXT_KH:
    add.u32 %r36, %r36, 1;
    bra LOOP_KH;
COMPUTE_DONE:
    bar.sync 0;
    add.u32 %r29, %r29, 1;
    bra LOOP_IC;
STORE:
    ld.param.u32 %r44, [has_bias];
    setp.eq.u32  %p12, %r44, 0;
    @%p12 bra WRITE;
    cvt.u64.u32 %rd10, %r7;
    shl.b64     %rd10, %rd10, 2;
    ld.param.u64 %rd11, [bias_ptr];
    add.u64     %rd12, %rd11, %rd10;
    ld.global.f32 %f4, [%rd12];
    add.f32     %f0, %f0, %f4;
    add.f32     %f1, %f1, %f4;
    add.f32     %f2, %f2, %f4;
    add.f32     %f3, %f3, %f4;
WRITE:
    mad.lo.u32 %r45, %r8, %r6, %r7;
    mad.lo.u32 %r45, %r45, %r9, %r11;
    mad.lo.u32 %r45, %r45, %r10, %r12;
    cvt.u64.u32 %rd13, %r45;
    shl.b64     %rd13, %rd13, 2;
    ld.param.u64 %rd14, [out_ptr];
    add.u64     %rd13, %rd13, %rd14;
    @%p13 st.global.f32 [%rd13], %f0;
    @%p14 st.global.f32 [%rd13+4], %f1;
    @%p15 st.global.f32 [%rd13+8], %f2;
    @%p16 st.global.f32 [%rd13+12], %f3;
DONE:
    ret;
}
"""
